class TafUeAndroidPool(ProxiedCfgFileBasedUePool, IAbstractTakeCarer):
    """UePool for Android UEs"""

    def __init__(self, config_file_path=None, inline_config=None, keep_reservation_duration=None):
        """

        :param config_file_path:
        :param inline_config:
        :param keep_reservation_duration:
        """
        if inline_config is None:
            inline_config = []
        super().__init__(config_file_path, inline_config)
        self.rpc_clients = set()
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL'})
        keep_reservation_duration = keep_reservation_duration or ANDROID_KEEP_RESERVATION_THREAD_UPDATE_DURATION
        self._keep_reservation_thread = TakeCareThread(self, keep_reservation_duration,
                                                       thread_namesufix='-in-TafUeAndroidPool')
        self._ues_reservation_list = UesReservationList(UE_RESERVATION_TIME)

