    def report_exception(self, key, value, exception):
        """
        Callback method for TakeCareThread class to keeping reservation
        :param key:
        :param value:
        :param exception:
        :return:
        """
        trace = traceback.format_exc()
        msg = f"Exception inside _run_thread_android_keep_reservation {exception} \ntrace\n{trace}"
        self.logger.warning(msg)

    def _withdraw_device_from_available_devices(self, device_name, ue):  # pylint: disable=arguments-differ
        self.logger.debug("start _withdraw_ue_from_available_ues, new version 20.07.2017")
        self._ues_reservation_list.update_ue_reservation_time(ue.ue_id)
        ue.start_reservation_veryfying()
        self._ues_reservation_list.update_ue_reservation_time(ue.ue_id)
        self._keep_reservation_thread.add_careable(device_name, ue)
        super()._withdraw_device_from_available_devices(device_name, ue)
        self.logger.debug("end _withdraw_ue_from_available_ues")

    def release_ue(self, ue):
        """
        Allow UE to be reused - it should be in pool of available UEs. (public API)
        :raises: :py:class:`ute_ue.exceptions.UnknownUe`: If given ue has not been returned from this pool via get_ue()
        :return: None
        """
        ue_id = ue.ue_id
        try:
            self._keep_reservation_thread.remove_careable(ue_id)
        except (KeyError, AttributeError):
            raise UnknownUe(f'UE: {ue_id} is not reserved from TafUeAndroidPool')

    def create_device(self, device_name, device_config):  # pylint: disable=arguments-differ
        """
        Create instance of device

        :param device_name: name of UE
        :param device_config: configuration of UE
        :return: device instance
        """
        try:
            self.logger.debug(f"Executing create_device with name {device_name} and configuration {device_config}")
            config = device_config['CONSTRUCTOR_PARAMETERS']['configuration']
            ue_id = device_config['CONSTRUCTOR_PARAMETERS']['serial_number']
            ue_class = self.get_device_class(class_name=device_config['CLASS'])
            config['access'] = device_config['CLASS'].lower().replace("ue", "")
            self.prepare_ueproxy_service(device_config)
            rpc_client = self.get_ueproxy_connection_client_by(config['ue_pc_address'])
            self.rpc_clients.add(rpc_client)
            constructor_params = {'name': device_name,
                                  'ue_id': ue_id,
                                  'configuration': config,
                                  'rpc_client': rpc_client,
                                  'reservation_validator': lambda: self._ues_reservation_list.is_still_reserved(ue_id)}
            self._ues_reservation_list.update_ue_reservation_time(ue_id)
            created_ue = instance_loader.create_class_instance(class_object=ue_class,
                                                               constructor_params=constructor_params)
            is_ue_preparation_successful = created_ue.prepare_ue()
            if not is_ue_preparation_successful:
                raise Exception(f"UE {ue_id} reservation failed")
            #   no need to use this? it was commented...
            # self._prepare_notification(self.connections[ip], config, ue_id,
            #                            device_name, ue_class, created_ue.ue_model)
            return created_ue
        except KeyError as e:
            trace = traceback.format_exc()
            raise InvalidConfigurationContent(f"Configuration is not valid for Android UE: {device_name}. "
                                              f"Expected keyword: {e.args[0]}\nMore trace: {trace}")

    _create_device = create_device  # for backward compatibility (deprecated but exists till all switch to new API)

    @classmethod
    def convert_device_type_2_device_class_fullname(cls, device_type):
        """
        Encapsulate convention how to produce full package.module.class name for given Device type

        (Default convention from ute_common_abstract_core/device_pool.py doesn't work for
        taf package structure)

        :param device_type: Device type (must be CamelCase name)
        :return: full package.module.class name
        """
        ue_type2class_fullname = {'AndroidUe': 'taf.ue.android.android_ue.AndroidUe',
                                  'SoundcardAndroidUe':
                                  'taf.ue.android.soundcard.soundcardandroid_ue.SoundcardAndroidUe',
                                  'QualcommNoLicenseUe': 'taf.ue.at_cmds_ue.at_cmds_ue.AtCmdsUe',
                                  'AtCmdsUe': 'taf.ue.at_cmds_ue.at_cmds_ue.AtCmdsUe'}
        class_fullname = ue_type2class_fullname[device_type]
        return class_fullname

    def shutdown(self):
        """
        Shutdown

        avoid: RuntimeError: dictionary changed size during iteration
        """
        for device_name in list(self._taken_devices):
            self._return_device_to_available_devices(device_name)
            self._keep_reservation_thread.remove_careable(device_name)
        self._keep_reservation_thread.clear_and_finish()

        if self._keep_reservation_thread.is_alive():
            self.logger.debug("Waiting for take care Thread to finish.")
            self._keep_reservation_thread.join()

        for rpc_client in self.rpc_clients:
            self.ueproxy_teardown(rpc_client)
